import{_ as t,o as i,c as l,a2 as e}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Day CERN 2019: Ceph at the Flatiron Institute - Andras Pataki","description":"","frontmatter":{"title":"Ceph Day CERN 2019: Ceph at the Flatiron Institute - Andras Pataki","date":"2020-08-25T00:00:00.000Z","updated":"2020-08-26T00:00:00.000Z","tags":["Ceph","Distributed Storage","Flatiron Institute","Performance","Data Recovery"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Day_CERN_2019_-_Ceph_at_the_Flatiron_Institute_-_Andras_Pataki.md","filePath":"posts/2020/Ceph_Day_CERN_2019_-_Ceph_at_the_Flatiron_Institute_-_Andras_Pataki.md","lastUpdated":1780459816000}'),r={name:"posts/2020/Ceph_Day_CERN_2019_-_Ceph_at_the_Flatiron_Institute_-_Andras_Pataki.md"};function o(n,a,_,s,h,p){return i(),l("div",null,[...a[0]||(a[0]=[e('<h3 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h3><p>Andres Pataki，来自Simon西班牙Flatiron研究所，在Ceph Day CERN 2019会议上介绍了Flatiron研究所的背景、Ceph存储系统的使用情况、技术细节、性能表现、硬件与软件挑战以及未来展望。</p><h4 id="关键细节" tabindex="-1">关键细节： <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节：&quot;">​</a></h4><ol><li><p><strong>Flatiron研究所背景</strong>：</p><ul><li>Flatiron研究所是Simons基金会的一个研究部门，专注于通过计算手段推进科学研究。</li><li>研究所拥有约150名科学家，涉及天体物理学、生物学、量子化学和数学等多个领域。</li></ul></li><li><p><strong>Ceph存储系统使用情况</strong>：</p><ul><li>研究所使用Ceph存储系统处理多种计算任务，包括基因组数据、早期宇宙的MPI模拟等。</li><li>集群规模：约40,000个核心，数百个GPU，存储空间约30PB。</li></ul></li><li><p><strong>技术细节与性能</strong>：</p><ul><li>Ceph的CRUSH算法在数据恢复方面表现出色，特别是在多重故障情况下。</li><li>性能测试显示，Ceph集群在处理大量数据时表现出色，但小文件性能仍有待提升。</li></ul></li><li><p><strong>硬件与软件挑战</strong>：</p><ul><li>硬件方面，早期购买的NAS级硬盘存在数据损坏问题。</li><li>网络方面，早期40G接口存在丢包问题。</li><li>软件方面，从Hammer版本升级到Mimic，并计划升级到Nautilus。</li></ul></li><li><p><strong>经验与教训</strong>：</p><ul><li>硬件测试至关重要，早期硬件问题导致数据损坏。</li><li>Ceph的滚动升级策略有效，未导致系统中断。</li><li>灾难恢复案例显示，Ceph的高冗余模型确保了数据安全。</li></ul></li><li><p><strong>未来展望</strong>：</p><ul><li>改进小文件性能是当前的主要挑战。</li><li>考虑引入闪存存储，关注Ceph的Crimson项目。</li><li>探索多站点支持，以实现不同地理位置之间的统一文件系统。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>继续关注并测试Ceph的新版本和功能。</li><li>优化小文件性能，考虑引入闪存存储。</li><li>探索多站点支持，以实现更广泛的存储部署。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>定期进行硬件和软件测试，确保系统稳定性。</li><li>持续监控和优化Ceph集群的性能。</li><li>与Ceph开发团队保持沟通，获取早期支持和修复。</li></ul><h4 id="结论" tabindex="-1">结论： <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论：&quot;">​</a></h4><p>Flatiron研究所通过使用Ceph存储系统，成功支持了多个科学研究项目，尽管面临硬件和软件挑战，但通过持续的优化和升级，确保了数据的安全和系统的稳定运行。未来，研究所将继续探索Ceph的新功能和优化方案，以满足不断增长的计算和存储需求。</p>',10)])])}const C=t(r,[["render",o]]);export{d as __pageData,C as default};
